17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.samples.petclinic.util.IdentityKeys;
40	import org.springframework.samples.petclinic.util.Membership;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        owner.setHouseholdId(Households.householdId(owner));
99	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
100	        int points = Membership.points(owner, Households.memberCount(this.clinicService.findAllOwners(), owner) >= 3, Tenure.exceedsOneYear(owner));
101	        ownerDto.setMembershipPoints(points);
102	        ownerDto.setMembershipLevel(Membership.level(points));
103	        Integer possibleDuplicateOf = PossibleDuplicates.matchId(this.clinicService.findAllOwners(), owner);
104	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
105	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
106	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        if (DisposableDomains.isBlocked(owner)) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        Collection<Owner> owners = this.clinicService.findAllOwners();
118	        if (DailyRegistrations.countOn(owners, java.time.LocalDate.now()) >= 100) {
119	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
120	        }
121	        if (CityCodes.count(owners, owner) >= 50) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        owner.setHouseholdId(Households.householdId(owner));
125	        if (IdentityKeys.isDuplicate(owners, owner)) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && Households.isDuplicate(owners, owner)) {
129	            return new ResponseEntity<>(HttpStatus.CONFLICT);
130	        }
131	        owner.setBulkSignupWarning(DailyRegistrations.countOn(owners, java.time.LocalDate.now()) > 80);
132	        owner.setNamesakeCount(Namesakes.count(owners, owner));
133	        owner.setCustomerCode(org.springframework.samples.petclinic.util.CustomerCodes.of(owner));
134	        this.clinicService.saveOwner(owner);
135	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
136	        headers.setLocation(UriComponentsBuilder.newInstance()
137	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
138	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
144	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
145	        if (currentOwner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        currentOwner.setAddress(ownerFieldsDto.getAddress());
149	        currentOwner.setCity(ownerFieldsDto.getCity());
150	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
151	        currentOwner.setLastName(ownerFieldsDto.getLastName());
152	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
153	        this.clinicService.saveOwner(currentOwner);
154	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Transactional
159	    @Override
160	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        this.clinicService.deleteOwner(owner);
166	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
172	        Owner owner = this.clinicService.findOwnerById(ownerId);
173	        if (owner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        HttpHeaders headers = new HttpHeaders();
177	        Pet pet = petMapper.toPet(petFieldsDto);
178	        owner.setId(ownerId);
179	        pet.setOwner(owner);
180	        pet.getType().setName(null);
181	        this.clinicService.savePet(pet);
182	        PetDto petDto = petMapper.toPetDto(pet);
183	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
184	            .buildAndExpand(pet.getId()).toUri());
185	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
191	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
192	        if (currentOwner != null) {
193	            Pet currentPet = this.clinicService.findPetById(petId);
194	            if (currentPet != null) {
195	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
196	                currentPet.setName(petFieldsDto.getName());
197	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
198	                this.clinicService.savePet(currentPet);
199	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
200	            }
201	        }
202	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
208	        HttpHeaders headers = new HttpHeaders();
209	        Visit visit = visitMapper.toVisit(visitFieldsDto);
210	        Pet pet = new Pet();
211	        pet.setId(petId);
212	        visit.setPet(pet);
213	        this.clinicService.saveVisit(visit);
214	        VisitDto visitDto = visitMapper.toVisitDto(visit);
215	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
216	            .buildAndExpand(visit.getId()).toUri());
217	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
218	    }
219	
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner != null) {
226	            Pet pet = owner.getPet(petId);
227	            if (pet != null) {
228	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
229	            }
230	        }
231	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	    }
233	}
