16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import org.springframework.samples.petclinic.util.BusinessDays;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	@EntityListeners(OwnerAuditListener.class)
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "telephone")
50	    @NotEmpty
51	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 format")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    private String email;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    public String getPostcode() {
61	        return this.postcode;
62	    }
63	
64	    public void setPostcode(String postcode) {
65	        this.postcode = postcode;
66	    }
67	
68	    @Column(name = "registration_date")
69	    private LocalDate registrationDate;
70	
71	    @Column(name = "birth_date")
72	    private LocalDate birthDate;
73	
74	    public LocalDate getBirthDate() {
75	        return this.birthDate;
76	    }
77	
78	    public void setBirthDate(LocalDate birthDate) {
79	        this.birthDate = birthDate;
80	    }
81	
82	    /** The owner's age band ('MINOR'/'ADULT'/'SENIOR') as of the registration date. */
83	    @Transient
84	    public String getAgeBand() {
85	        return org.springframework.samples.petclinic.util.AgeBands.of(this.birthDate, this.registrationDate);
86	    }
87	
88	    @Column(name = "customer_code")
89	    private String customerCode;
90	
91	    public String getCustomerCode() {
92	        return this.customerCode;
93	    }
94	
95	    public void setCustomerCode(String customerCode) {
96	        this.customerCode = customerCode;
97	    }
98	
99	    /** Assign the customer code '<CITY3>-<LAST3>-<NNNN>' for the given per-city sequence number. */
100	    public void assignCustomerCode(int sequence) {
101	        this.customerCode = getCity().substring(0, 3).toUpperCase() + "-"
102	            + getLastName().substring(0, 3).toUpperCase() + String.format("-%04d", sequence);
103	    }
104	
105	    @Transient
106	    private String householdId;
107	
108	    public String getHouseholdId() {
109	        return this.householdId;
110	    }
111	
112	    public void setHouseholdId(String householdId) {
113	        this.householdId = householdId;
114	    }
115	
116	    @Transient
117	    private Integer namesakeCount;
118	
119	    public Integer getNamesakeCount() {
120	        return this.namesakeCount;
121	    }
122	
123	    public void setNamesakeCount(Integer namesakeCount) {
124	        this.namesakeCount = namesakeCount;
125	    }
126	
127	    @Transient
128	    private Boolean bulkSignupWarning;
129	
130	    public Boolean getBulkSignupWarning() {
131	        return this.bulkSignupWarning;
132	    }
133	
134	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
135	        this.bulkSignupWarning = bulkSignupWarning;
136	    }
137	
138	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
139	    private Set<Pet> pets;
140	
141	    public String getEmail() {
142	        return this.email;
143	    }
144	
145	    /** Store the email lower-cased so it is persisted and returned normalised. */
146	    public void setEmail(String email) {
147	        this.email = (email == null) ? null : email.toLowerCase();
148	    }
149	
150	    public LocalDate getRegistrationDate() {
151	        return this.registrationDate;
152	    }
153	
154	    public void setRegistrationDate(LocalDate registrationDate) {
155	        this.registrationDate = registrationDate;
156	    }
157	
158	    /** Default a missing registration date to the server's current date, then roll the
159	     *  effective date forward to a business day (a weekend becomes the next Monday). */
160	    @PrePersist
161	    protected void ensureRegistrationDate() {
162	        LocalDate effective = (this.registrationDate == null) ? LocalDate.now() : this.registrationDate;
163	        this.registrationDate = BusinessDays.rollForward(effective);
164	    }
165	
166	    public String getAddress() {
167	        return this.address;
168	    }
169	
170	    public void setAddress(String address) {
171	        this.address = address;
172	    }
173	
174	    public String getCity() {
175	        return this.city;
176	    }
177	
178	    public void setCity(String city) {
179	        this.city = city;
180	    }
181	
182	    public String getTelephone() {
183	        return this.telephone;
184	    }
185	
186	    public void setTelephone(String telephone) {
187	        this.telephone = telephone;
188	    }
189	
190	    protected Set<Pet> getPetsInternal() {
191	        if (this.pets == null) {
192	            this.pets = new HashSet<>();
193	        }
194	        return this.pets;
195	    }
196	
197	    protected void setPetsInternal(Set<Pet> pets) {
198	        this.pets = pets;
199	    }
200	
201	    public List<Pet> getPets() {
202	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
203	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
204	        return Collections.unmodifiableList(sortedPets);
205	    }
206	
207	    public void setPets(List<Pet> pets) {
208	        this.pets = new HashSet<>(pets);
209	    }
210	
211	    public void addPet(Pet pet) {
212	        getPetsInternal().add(pet);
213	        pet.setOwner(this);
214	    }
215	
216	    /**
217	     * Return the Pet with the given name, or null if none found for this Owner.
218	     *
219	     * @param name to test
220	     * @return true if pet name is already in use
221	     */
222	    public Pet getPet(String name) {
223	        return getPet(name, false);
224	    }
225	
226	    /**
227	     * Return the Pet with the given name, or null if none found for this Owner.
228	     *
229	     * @param name to test
230	     * @return true if pet name is already in use
231	     */
232	    public Pet getPet(String name, boolean ignoreNew) {
233	        name = name.toLowerCase();
234	        for (Pet pet : getPetsInternal()) {
235	            if (!ignoreNew || !pet.isNew()) {
236	                String compName = pet.getName();
237	                compName = compName.toLowerCase();
238	                if (compName.equals(name)) {
239	                    return pet;
240	                }
241	            }
242	        }
243	        return null;
244	    }
245	
246	    public Pet getPet(Integer petId) {
247	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
248	    }
249	
250	    @Override
251	    public String toString() {
252	        return new ToStringCreator(this)
253	
254	            .append("id", this.getId())
255	            .append("new", this.isNew())
256	            .append("lastName", this.getLastName())
257	            .append("firstName", this.getFirstName())
258	            .append("address", this.address)
259	            .append("city", this.city)
260	            .append("telephone", this.telephone)
261	            .toString();
262	    }
263	}
