10	final class DisposableDomains {
11	
12	    private static final Set<String> BLOCKED = Set.of(
13	        "mailinator.com", "tempmail.com", "guerrillamail.com");
14	
15	    private DisposableDomains() {
16	    }
17	
18	    /** Whether the owner's email domain is a blocked disposable domain. */
